class InventoryPage extends StatefulWidget { const InventoryPage({super.key}); @override State<InventoryPage> createState()=>_InventoryPageState(); }
class _InventoryPageState extends State<InventoryPage>{ List<RetailProduct> _products=[]; bool _loading=true; @override void initState(){super.initState();unawaited(_load());} Future<void> _load()async{final p=await RetailDb.searchProducts('');if(mounted)setState((){_products=p;_loading=false;});}
  Future<void> _adjust(RetailProduct product) async { final qty=TextEditingController(); final note=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text('Adjust ${product.name}'),content:SizedBox(width:360,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:qty,keyboardType:const TextInputType.numberWithOptions(decimal:true,signed:true),decoration:const InputDecoration(labelText:'Quantity change (+ or -)')),const SizedBox(height:12),TextField(controller:note,decoration:const InputDecoration(labelText:'Reason'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])); if(ok==true){final delta=double.tryParse(qty.text);if(delta!=null&&delta!=0){await RetailDb.adjustStock(product.id,delta,note.text.trim().isEmpty?'Manual adjustment':note.text.trim());await _load();}} }
  @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const _ScreenHeader(storeName:'Retail',title:'Inventory',subtitle:'Local stock on hand and adjustments'),const SizedBox(height:16),Expanded(child:_loading?const Center(child:CircularProgressIndicator()):Card(child:SingleChildScrollView(child:SizedBox(width:double.infinity,child:DataTable(columns:const[DataColumn(label:Text('Barcode')),DataColumn(label:Text('Product')),DataColumn(label:Text('Category')),DataColumn(label:Text('Price'),numeric:true),DataColumn(label:Text('Stock'),numeric:true),DataColumn(label:Text('Action'))],rows:_products.map((p)=>DataRow(cells:[DataCell(Text(p.barcode)),DataCell(Text(p.name)),DataCell(Text(p.category)),DataCell(Text('\$${p.price.toStringAsFixed(2)}')),DataCell(Text(p.stock.toStringAsFixed(2),style:TextStyle(color:p.stock<=5?BlueIce.error:BlueIce.text))),DataCell(IconButton(onPressed:()=>_adjust(p),icon:const Icon(Icons.tune)))])).toList())))))]));}
